// Original adaptive score. All notes are scheduled against the audio clock.
export const SCORE={bpm:112,roots:[45,41,48,43],melody:[12,19,22,19,15,19,24,22,12,19,27,24,22,19,15,19]};
export function exertionTarget(player,playing){return !playing?0:player?.isSprinting?1:player?.hp<30?.55:0}
export class Soundscape{
 constructor(ctx,master){this.ctx=ctx;this.music=ctx.createGain();this.voice=ctx.createGain();this.music.connect(master);this.voice.connect(master);this.beat=0;this.next=ctx.currentTime+.08;this.breathAt=0;this.exertion=0;this.lastGrunt=-10;this.duckUntil=0;this.settings={musicVolume:.65,voiceVolume:.8};
  this.noise=ctx.createBuffer(1,ctx.sampleRate,ctx.sampleRate);const d=this.noise.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=Math.random()*2-1;
 }
 tone(note,time,duration,volume,type='triangle'){const c=this.ctx,o=c.createOscillator(),g=c.createGain();o.type=type;o.frequency.value=440*2**((note-69)/12);g.gain.setValueAtTime(.001,time);g.gain.exponentialRampToValueAtTime(volume,time+.012);g.gain.exponentialRampToValueAtTime(.001,time+duration);o.connect(g).connect(this.music);o.start(time);o.stop(time+duration+.02);o.onended=()=>{o.disconnect();g.disconnect()}}
 drum(time,kick){const c=this.ctx,s=kick?c.createOscillator():c.createBufferSource(),g=c.createGain();if(kick){s.frequency.setValueAtTime(130,time);s.frequency.exponentialRampToValueAtTime(40,time+.13)}else s.buffer=this.noise;const f=c.createBiquadFilter();f.type=kick?'lowpass':'highpass';f.frequency.value=kick?300:6500;g.gain.setValueAtTime(kick?.7:.065,time);g.gain.exponentialRampToValueAtTime(.001,time+(kick?.22:.06));s.connect(f).connect(g).connect(this.music);s.start(time);s.stop(time+.25);s.onended=()=>{s.disconnect();f.disconnect();g.disconnect()}}
 breath(strength){const c=this.ctx,t=c.currentTime;for(const [offset,length,volume,freq]of [[0,.42,.20,850],[.55,.55,.30,1100]]){const s=c.createBufferSource(),f=c.createBiquadFilter(),g=c.createGain();s.buffer=this.noise;f.type='bandpass';f.frequency.value=freq;f.Q.value=.8;g.gain.setValueAtTime(.001,t+offset);g.gain.linearRampToValueAtTime(volume*strength,t+offset+length*.35);g.gain.exponentialRampToValueAtTime(.001,t+offset+length);s.connect(f).connect(g).connect(this.voice);s.start(t+offset);s.stop(t+offset+length);s.onended=()=>{s.disconnect();f.disconnect();g.disconnect()}}}
 duck(){this.duckUntil=this.ctx.currentTime+2.5}
 update(dt,{phase='menu',player=null,intermission=0,wave=0,hidden=false}={},settings=this.settings){this.settings=settings;const c=this.ctx,playing=phase==='playing'&&!hidden,paused=phase==='paused'||hidden;this.voice.gain.setTargetAtTime(paused?0:settings.voiceVolume??.8,c.currentTime,.08);const intensity=playing&&!intermission?Math.min(1,.35+wave*.045):.18;this.music.gain.setTargetAtTime((paused?0:settings.musicVolume??.65)*(c.currentTime<this.duckUntil?.38:1),c.currentTime,.15);
  this.exertion+=(exertionTarget(player,playing)-this.exertion)*(1-Math.exp(-dt/(playing&&player?.isSprinting?2:4)));
  if(playing&&this.exertion>.12&&c.currentTime>this.breathAt){this.breath(Math.min(.9,this.exertion));this.breathAt=c.currentTime+2.6-this.exertion*1.2}
  if(paused){this.next=c.currentTime+.1;return}if(this.next<c.currentTime-.1)this.next=c.currentTime+.04;
  while(this.next<c.currentTime+.18){const b=this.beat,root=SCORE.roots[Math.floor(b/32)%4],t=this.next; if(b%8===0){for(const n of [0,7,14])this.tone(root+n,t,2.1,.075,'sine')}if(b%2===0)this.tone(root+(b%8===6?7:0),t,.19,.30);if(b%4===0)this.drum(t,true);if(intensity>.35){this.drum(t,false);if(b%8===4){this.drum(t+.018,false);this.tone(62,t,.09,.07,'triangle')}}if(b%4===2)this.tone(root+SCORE.melody[Math.floor(b/4)%16],t,.32,.11+intensity*.07);if(intensity>.65&&b%2===1)this.tone(root+24+(b%8===3?7:0),t,.10,.08,'sine');this.beat++;this.next+=60/SCORE.bpm/4;}
 }
}
